        } else if (TestProfileRunStatus.FAILED.equals(testProfileRun.getStatus())) {
            lroStatus = LongRunningOperationStatus.FAILED;
        } else if (TestProfileRunStatus.CANCELLED.equals(testProfileRun.getStatus())) {
